// Extract incoming body from EasyEvent backend
const item = $input.first().json;
const body = item.body || item;

const workId = body.workId || `work-${Date.now()}`;
const workType = body.workType || 'UNKNOWN';
const action = body.action || 'unspecified';
const table = body.table || 'unknown';
const operation = body.operation || 'MUTATION';
const timestamp = body.timestamp || new Date().toISOString();

// User Identification
const userIdent = body.userIdentification || {};
const primaryUser = userIdent.primary || {};
const actor = userIdent.actor || primaryUser;
const target = userIdent.target || null;

// Normalize phone & UPI ID
const rawPhone = primaryUser.phone || '';
const cleanPhone = String(rawPhone).replace(/[^0-9]/g, '');
const is10DigitIndianNumber = cleanPhone.length === 10;
const upiId = primaryUser.upiId || (cleanPhone ? `${cleanPhone}@upi` : 'N/A');

// Evaluate disciplinary and risk profile
const warnings = Number(primaryUser.warnings) || 0;
const isSuspended = primaryUser.accountStatus === 'suspended';
let riskProfile = 'CLEAN_VERIFIED';
if (isSuspended) {
  riskProfile = 'BLOCKED_SUSPENDED';
} else if (warnings >= 1) {
  riskProfile = 'WARNING_MONITOR';
}

return [{
  json: {
    workId,
    workType,
    action,
    table,
    operation,
    timestamp,
    userIdentification: {
      userId: primaryUser.userId || 'anon',
      name: primaryUser.name || 'Unknown User',
      email: primaryUser.email || 'N/A',
      role: primaryUser.role || 'worker',
      phone: primaryUser.phone || null,
      upiId,
      upiValid: is10DigitIndianNumber,
      accountStatus: primaryUser.accountStatus || 'active',
      warnings,
      riskProfile,
      actor: {
        userId: actor.userId,
        name: actor.name,
        role: actor.role
      },
      target: target ? {
        userId: target.userId,
        name: target.name,
        phone: target.phone,
        upiId: target.upiId
      } : null
    },
    payload: body.databaseWork ? body.databaseWork.payload : (body.payload || {}),
    metadata: body.metadata || {}
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

// Calculate UPI instant payout in Indian Rupees (₹)
const baseAmount = Number(payload.payoutAmount) || 2500;
const currency = 'INR';
const upiTarget = user.upiId;

return [{
  json: {
    automationStep: 'UPI_PAYOUT_DISPATCH',
    status: 'PAYOUT_INITIATED',
    worker: {
      name: user.name,
      email: user.email,
      phone: user.phone,
      upiId: upiTarget,
      status: 'VERIFIED_ATTENDED'
    },
    transaction: {
      referenceId: `UPI-${Date.now()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
      shiftId: payload.shiftId,
      amount: baseAmount,
      currency,
      displayAmount: `₹${baseAmount}`,
      destinationUPI: upiTarget,
      paymentMode: 'IMPS_UPI_INSTANT',
      note: `EasyEvent Bengaluru Payout for ${payload.title || 'Event Crew'}`
    },
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

const strikes = (user.warnings || 0);
const isSuspension = strikes >= 2 || user.riskProfile === 'BLOCKED_SUSPENDED';

return [{
  json: {
    automationStep: 'DISCIPLINARY_ACTION_TRIGGERED',
    status: isSuspension ? 'ACCOUNT_SUSPENDED_48H' : 'PAYOUT_DELAYED_WARNING',
    worker: {
      name: user.name,
      email: user.email,
      phone: user.phone,
      warningStrikes: strikes,
      suspendedUntil: payload.suspendedUntil || null
    },
    penaltyPolicy: {
      actionTaken: isSuspension
        ? 'Account suspended for 2 days. Payout withheld pending manual compliance review.'
        : 'Warning 1 logged. Payout delayed by 48 hours for attendance re-verification.',
      supervisorAlertDispatched: true,
      shiftId: payload.shiftId,
      eventTitle: payload.title
    },
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

return [{
  json: {
    automationStep: 'SHIFT_BOOKING_CONFIRMED',
    status: 'SLOT_RESERVED',
    worker: {
      name: user.name,
      phone: user.phone,
      upiId: user.upiId
    },
    shift: {
      shiftId: payload.shiftId,
      eventId: payload.eventId,
      title: payload.title,
      duty: payload.duty,
      date: payload.date,
      time: payload.time
    },
    briefingAlertDispatched: true,
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

return [{
  json: {
    automationStep: 'SHIFT_CANCELLED_SLOT_RELEASED',
    status: 'SLOT_RESTORED_TO_POOL',
    worker: {
      name: user.name,
      phone: user.phone
    },
    shiftId: payload.shiftId,
    eventId: payload.eventId,
    policyCheck: 'Cancelled within 4-hour grace window. No disciplinary penalty applied.',
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

return [{
  json: {
    automationStep: 'USER_ONBOARDING_INITIALIZED',
    status: 'ACCOUNT_CREATED',
    user: {
      userId: user.userId,
      name: user.name,
      email: user.email,
      role: user.role,
      phone: user.phone,
      upiId: user.upiId,
      upiValid: user.upiValid
    },
    welcomeAlert: user.role === 'worker'
      ? `Welcome ${user.name} to Bengaluru Crew Hub! Your UPI payout handle is verified: ${user.upiId}`
      : `Welcome ${user.name} to EasyEvent Organizer Console!`,
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const user = item.userIdentification;
const payload = item.payload;

return [{
  json: {
    automationStep: 'EVENT_STAFFING_BROADCAST',
    status: 'CREW_NOTIFIED',
    organizer: {
      name: user.name,
      email: user.email
    },
    event: {
      eventId: payload.eventId,
      title: payload.title,
      venue: payload.venue,
      requiredCrew: payload.required,
      duty: payload.duty,
      date: payload.date,
      time: payload.time
    },
    broadcastChannels: ['Bengaluru Crew Push Notification', 'Worker Available Roster Feed'],
    workId: item.workId,
    processedAt: new Date().toISOString()
  }
}];

const inputItems = $input.all();
const results = inputItems.map(item => ({
  workId: item.json.workId,
  automationStep: item.json.automationStep,
  status: item.json.status,
  completedAt: new Date().toISOString(),
  summary: `Identified and processed database work [${item.json.automationStep}] successfully.`
}));

return results;
